  "You have one of the three best cars: sacrificing the present sours the board": "У вас одна из трех лучших машин: жертвование настоящим портит совет директоров",
  "Tienes uno de los tres mejores coches: sacrificar el presente enfada al consejo": "У вас одна из трех лучших машин: жертвование настоящим портит совет директоров",
  "A pinch from every remaining year, and a debut without extremes: no jackpot, no disaster.": "По щепотке из каждого оставшегося года и дебют без крайностей: ни джекпота, ни катастрофы.",
  "Un pellizco cada año que queda, y un estreno sin extremos: ni el pelotazo ni el desastre.": "По щепотке из каждого оставшегося года и дебют без крайностей: ни джекпота, ни катастрофы.",
