  "You COMPLETE the Triple Crown! A club of one — only Graham Hill had ever done it.": "Вы ЗАВЕРШАЕТЕ Тройную Корону! Клуб одного – только Грэм Хилл когда-либо делал это.",
  "¡COMPLETAS la Triple Corona! Un club de uno: solo Graham Hill lo había logrado jamás.": "Вы ЗАВЕРШАЕТЕ Тройную Корону! Клуб одного – только Грэм Хилл когда-либо делал это.",
  "Three karting teams want you. The kart isn't everything: pick the project that develops you best.": "Тебя хотят три картинговые команды. Картинг – это еще не все: выберите проект, который развивает вас лучше всего.",
  "Tres equipos de karting te quieren. No solo importa el coche: elige qué proyecto te forma mejor.": "Тебя хотят три картинговые команды. Картинг – это еще не все: выберите проект, который развивает вас лучше всего.",
  "Three karting academies want you. The kart isn't everything: pick the project that develops you best.": "Ты нужен трем академиям картинга. Картинг – это еще не все: выберите проект, который развивает вас лучше всего.",
  "Tres academias de karting te quieren. No solo importa el coche: elige qué proyecto te forma mejor.": "Ты нужен трем академиям картинга. Картинг – это еще не все: выберите проект, который развивает вас лучше всего.",
