  "You become the drivers' voice: the fans idolise you. +20% fame": "Вы становитесь голосом гонщиков: болельщики боготворят вас. +20% славы",
  "Te conviertes en la voz de los pilotos: la afición te idolatra. +20% fama": "Вы становитесь голосом гонщиков: болельщики боготворят вас. +20% славы",
  "A dubiously-managed safety car on the last lap HANDS you the win: you take it with an asterisk. 🏆": "Сомнительно управляемая болид безопасности на последнем круге ВРУЧАЕТ вам победу: вы берете ее со звездочкой. 🏆",
  "Un coche de seguridad de gestión dudosa en la última vuelta te REGALA la victoria: te la llevas con asterisco. 🏆": "Сомнительно управляемая болид безопасности на последнем круге ВРУЧАЕТ вам победу: вы берете ее со звездочкой. 🏆",
  "A dubiously-managed safety car on the last lap ROBS you of a win you already had in the bag.": "Сомнительно управляемая болид безопасности на последнем круге ЛИШАЕТ у вас уже имевшуюся в сумке победу.",
  "Un coche de seguridad de gestión dudosa en la última vuelta te ARREBATA la victoria que ya tenías en el bolsillo.": "Сомнительно управляемая болид безопасности на последнем круге ЛИШАЕТ у вас уже имевшуюся в сумке победу.",
  "A lot of noise, but a week later nobody remembers. No change.": "Много шума, но через неделю никто не помнит. Никаких изменений.",
  "Mucho ruido, pero en una semana nadie se acuerda. Sin cambios.": "Много шума, но через неделю никто не помнит. Никаких изменений.",
  "Your take gets lost in the noise. No change.": "Ваш дубль теряется в шуме. Никаких изменений.",
  "Tu opinión pasa desapercibida entre el ruido. Sin cambios.": "Ваш дубль теряется в шуме. Никаких изменений.",
  "You rise above the mud and focus on your job. No change.": "Вы поднимаетесь над грязью и сосредотачиваетесь на своей работе. Никаких изменений.",
  "Te mantienes por encima del barro y a lo tuyo. Sin cambios.": "Вы поднимаетесь над грязью и сосредотачиваетесь на своей работе. Никаких изменений.",
  "Kick off in front of the cameras": "Начни перед камерами",
  "Montar el pollo delante de las cámaras": "Начни перед камерами",
  "Race control stops the Grand Prix for rain at half distance and takes the order from the lap before: it ROBS you of a win you already had in the bag.": "Контроль гонки останавливает Гран-при из-за дождя на половине дистанции и принимает приказ с предыдущего круга: это ЛИШАЕТ у вас уже имевшуюся в сумке победу.",
  "Dirección de carrera para el Gran Premio por la lluvia a mitad de distancia y da por buena la vuelta anterior: te ARREBATA la victoria que ya tenías en el bolsillo.": "Контроль гонки останавливает Гран-при из-за дождя на половине дистанции и принимает приказ с предыдущего круга: это ЛИШАЕТ у вас уже имевшуюся в сумке победу.",
  "Kick off on the radio": "Начните по радио",
