  "Ni entrar al trapo": "Не попадайся на удочку",
  "Call out the farce in the press": "Вызовите фарс в прессе",
  "Denunciar el paripé en rueda de prensa": "Вызовите фарс в прессе",
  "Race control starts the race on a soaked track with half the field on slicks. Half the grid ends up in the gravel; the other half gets lucky.": "Служба контроля гонки начинает гонку на мокрой трассе, где половина поля находится на сликах. Половина стартовой решётки оказывается в гравии; другой половине повезет.",
  "Dirección de carrera da la salida con la pista empapada y medio pelotón con gomas de seco. Media parrilla acaba en la grava; la otra media se libra por suerte.": "Служба контроля гонки начинает гонку на мокрой трассе, где половина поля находится на сликах. Половина стартовой решётки оказывается в гравии; другой половине повезет.",
  "Race control closes the pit lane at the wrong moment: it wrecks half the grid while the other half escapes by seconds.": "Контроль гонки закрывает пит-лейн в неподходящий момент: половина стартовой решетки разрушается, а другая половина убегает на секунды.",
  "Dirección de carrera cierra el pit-lane a destiempo: arruina a media parrilla mientras la otra media se libra por segundos.": "Контроль гонки закрывает пит-лейн в неподходящий момент: половина стартовой решетки разрушается, а другая половина убегает на секунды.",
  "Look the other way": "Посмотрите в другую сторону",
