  "The car is struggling. You can stay every night with the mechanics chasing tenths.": "болид борется. Можно каждую ночь оставаться с механиками в погоне за десятыми.",
  "El coche va mal. Puedes quedarte cada noche con los mecánicos buscando décimas.": "болид борется. Можно каждую ночь оставаться с механиками в погоне за десятыми.",
  "An oil company offers you a huge personal contract. It demands events every week.": "Нефтяная компания предлагает вам огромный личный контракт. Это требует событий каждую неделю.",
  "Una petrolera te ofrece un contrato personal millonario. Exige eventos cada semana.": "Нефтяная компания предлагает вам огромный личный контракт. Это требует событий каждую неделю.",
