  "La prensa te pinta como antipático. Fama -8%": "Пресса изображает вас недружелюбным человеком. Слава -8%",
  "A streaming platform wants to film your documentary all season. Global fame… with mics everywhere.": "Стриминговая платформа хочет снимать ваш документальный фильм весь сезон. Всемирная слава… микрофоны повсюду.",
