  "Te invitan a correr las 24h de Le Mans en tu semana libre. Gloria extra… o fatiga extra.": "Вас приглашают принять участие в гонке «24 часа Ле-Мана» в выходные дни. Дополнительная слава… или дополнительная усталость.",
  "Try it": "Попробуйте это",
  "Probarlo": "Попробуйте это",
  "A revolutionary trainer promises tenths with a never-seen method: a hypoxic chamber, diets weighed to the gram and a sports psychologist.": "Революционный тренер обещает десятые доли невиданным методом: гипоксическая камера, взвешенные до грамма диеты и спортивный психолог.",
  "Un preparador revolucionario promete décimas con un método nunca visto: cámara de hipoxia, dietas al gramo y un psicólogo deportivo.": "Революционный тренер обещает десятые доли невиданным методом: гипоксическая камера, взвешенные до грамма диеты и спортивный психолог.",
  "A revolutionary trainer promises tenths with a never-seen method: strict diet, biorhythms and sophrology.": "Революционный тренер обещает десятые доли невиданным методом: строгая диета, биоритмы и софрология.",
  "Un preparador revolucionario promete décimas con un método nunca visto: dieta estricta, biorritmos y sofrología.": "Революционный тренер обещает десятые доли невиданным методом: строгая диета, биоритмы и софрология.",
