  "En el paddock te cuelgan el cartel de aburrido. Fama -5%": "Паддок навешивает на тебя скучный ярлык. Слава -5%",
  "A revolutionary trainer promises tenths with a never-seen method: cryotherapy, neuroscience and fasting.": "Революционный тренер обещает десятые доли невиданным методом: криотерапия, нейробиология и голодание.",
  "Un preparador revolucionario promete décimas con un método nunca visto: crioterapia, neurociencia y ayuno.": "Революционный тренер обещает десятые доли невиданным методом: криотерапия, нейробиология и голодание.",
