  "A journalist has messages of yours harshly criticising the team. He publishes tomorrow.": "У журналиста есть ваши сообщения с резкой критикой команды. Он опубликует завтра.",
  "Un periodista tiene mensajes tuyos criticando duramente al equipo. Publica mañana.": "У журналиста есть ваши сообщения с резкой критикой команды. Он опубликует завтра.",
  "You pay and it's published anyway. Double disaster. -12% fame and internal fallout": "Вы платите, и оно все равно публикуется. Двойная катастрофа. -12% известности и внутренних последствий",
  "Paga y aún así se publica. Doble desastre. -12% fama y bronca interna": "Вы платите, и оно все равно публикуется. Двойная катастрофа. -12% известности и внутренних последствий",
  "The story dies in a drawer. -12% fame": "История умирает в ящике стола. -12% славы",
  "La historia muere en un cajón. -12% fama": "История умирает в ящике стола. -12% славы",
  "Go it alone": "Иди в одиночку",
