  "Aerodinámica": "Аэродинамика",
  "My F1 Glory career 🏁 Can you beat my legacy? f1-glory.com": "Моя карьера в славе F1 🏁 Сможете ли вы победить мое наследие? f1-glory.com",
  "Mi carrera en F1 Glory 🏁 ¿Superas mi legado? f1-glory.com": "Моя карьера в славе F1 🏁 Сможете ли вы победить мое наследие? f1-glory.com",
  "🌀 Years of dominating with the same car take their toll: rivals copy your concept and the rules trim you back. Staying on top will have to be paid for.": "🌀 Годы доминирования на одной и той же болиду берут свое: соперники копируют вашу концепцию, а правила урезают вас. За то, чтобы оставаться на вершине, придется платить.",
  "🌀 Años dominando con el mismo coche pasan factura: los rivales copian tu concepto y el reglamento te recorta. Mantenerse arriba habrá que pagarlo.": "🌀 Годы доминирования на одной и той же болиду берут свое: соперники копируют вашу концепцию, а правила урезают вас. За то, чтобы оставаться на вершине, придется платить.",
  "Reliability": "Надежность",
  "Fiabilidad": "Надежность",
