  "Motor": "Двигатель",
  "💼 Short-term CEO": "💼 Краткосрочный генеральный директор",
  "💼 CEO cortoplacista": "💼 Краткосрочный генеральный директор",
  "🏆 Ambitious CEO": "🏆 Амбициозный генеральный директор",
  "🏆 CEO ambicioso": "🏆 Амбициозный генеральный директор",
  "The team is yours. Nobody can sack you… but the books don't forgive.": "Команда ваша. Никто не может тебя уволить… но книги не прощают.",
  "El equipo es tuyo. Nadie te puede echar… pero las cuentas no perdonan.": "Команда ваша. Никто не может тебя уволить… но книги не прощают.",
  "Avoids failures: the car that finishes always scores": "Избегает неудач: болид, которая финиширует, всегда выигрывает",
  "Evita averías: el coche que termina siempre suma": "Избегает неудач: болид, которая финиширует, всегда выигрывает",
  "Top speed and corner exit: where the lap time is won": "Максимальная скорость и выход из поворота: где выигрывается время круга",
  "Velocidad punta y salida de curva: donde se gana el tiempo": "Максимальная скорость и выход из поворота: где выигрывается время круга",
  "Raises the ceiling, not the floor: outstanding years… or wasted ones": "Поднимает потолок, а не пол: выдающиеся годы… или потраченные впустую",
  "Sube el techo, no el suelo: años extraordinarios… o a medias": "Поднимает потолок, а не пол: выдающиеся годы… или потраченные впустую",
  "🧑‍✈️ Owner: YOU": "🧑‍✈️ Владелец: ВЫ",
  "🧑‍✈️ Dueño: TÚ": "🧑‍✈️ Владелец: ВЫ",
  "📣 Showman CEO": "📣 Генеральный директор шоумена",
  "📣 CEO showman": "📣 Генеральный директор шоумена",
  "🏭 Works-team CEO": "🏭 Генеральный директор Works-команды",
  "🏭 CEO de fábrica": "🏭 Генеральный директор Works-команды",
  "🌱 Patient CEO": "🌱 Генеральный директор пациента",
  "🌱 CEO paciente": "🌱 Генеральный директор пациента",
  "He answers to a manufacturer: he arrives with a real budget and the brand looking over his shoulder.": "Он отвечает перед производителем: он приходит с реальным бюджетом и брендом, который смотрит через его плечо.",
  "Responde ante un constructor: llega con presupuesto de verdad y con la marca mirando por encima del hombro.": "Он отвечает перед производителем: он приходит с реальным бюджетом и брендом, который смотрит через его плечо.",
  "Positions bore him: what he wants is front pages.": "Должности утомляли его: ему нужны первые полосы.",
  "Los puestos le aburren: lo suyo son las portadas.": "Должности утомляли его: ему нужны первые полосы.",
  "He believes in long projects and says so to your face: you'll have time, as long as the team is going somewhere.": "Он верит в длинные проекты и говорит это в лицо: успеешь, лишь бы команда куда-то шла.",
  "Cree en los proyectos largos y te lo dice a la cara: tendrás tiempo, mientras el equipo vaya a alguna parte.": "Он верит в длинные проекты и говорит это в лицо: успеешь, лишь бы команда куда-то шла.",
  "He doesn't look past December: he wants results this year, and next year we'll talk.": "Он не смотрит на декабрь: он хочет результатов в этом году, а в следующем году мы поговорим.",
  "No mira más allá de diciembre: quiere resultados este año, y del que viene ya hablaremos.": "Он не смотрит на декабрь: он хочет результатов в этом году, а в следующем году мы поговорим.",
  "Create your own team": "Создайте свою собственную команду",
  "Crea tu propio equipo": "Создайте свою собственную команду",
  "15 characters at most, or it won't fit in the standings.": "Максимум 15 персонажей, иначе он не поместится в турнирную таблицу.",
  "Como mucho 15 caracteres: si no, no cabe en las clasificaciones.": "Максимум 15 персонажей, иначе он не поместится в турнирную таблицу.",
  "The name needs a letter: that's where the crest comes from.": "В имени нужна буква: отсюда и герб.",
  "El nombre necesita alguna letra: de ahí sale el escudo.": "В имени нужна буква: отсюда и герб.",
  "Winning is all he understands, and he doesn't hide it. He wants the top, and to stay there.": "Победа – это все, что он понимает, и не скрывает этого. Он хочет вершины и остаться там.",
  "Solo entiende de ganar, y no lo disimula. Quiere llegar a lo más alto y mantenerse.": "Победа – это все, что он понимает, и не скрывает этого. Он хочет вершины и остаться там.",
  "Your name, your colours": "Ваше имя, ваши цвета",
  "Tu nombre, tus colores": "Ваше имя, ваши цвета",
  "Give it a name of at least two letters.": "Дайте ему имя минимум из двух букв.",
  "Ponle un nombre de al menos dos letras.": "Дайте ему имя минимум из двух букв.",
  "Your name, your colours and your CEO. You start last, with empty seats.": "Ваше имя, ваши цвета и ваш генеральный директор. Вы стартуете последним, с пустыми местами.",
  "Tu nombre, tus colores y tu CEO. Empiezas el último y con los asientos vacíos.": "Ваше имя, ваши цвета и ваш генеральный директор. Вы стартуете последним, с пустыми местами.",
  "🧑‍💼 Choose your team": "🧑‍💼 Выбери свою команду",
  "🧑‍💼 Elige tu escudería": "🧑‍💼 Выбери свою команду",
  "× Drivers' title (your drivers)": "× Должность водителя (ваши водители)",
  "× Mundial de tus pilotos": "× Должность водителя (ваши водители)",
  "Team name": "Название команды",
  "Nombre del equipo": "Название команды",
  "A team in the game already has that name.": "Команда в игре уже имеет такое название.",
